//! Fixed original substitution DTO copies, with work at every owned child.
use super::{IndustrialOwnerReadonlyFactsV1,readonly_industrial_data as data};
use oasis7_agent_api::world_action::*;
use oasis7_wasm_abi::*;
use std::{collections::BTreeMap,mem::size_of};
pub(super) fn vector<S:IndustrialOwnerReadonlyFactsV1,T,U>(s:&S,values:&[T],mut copy:impl FnMut(&T)->Result<U,S::Error>)->Result<Vec<U>,S::Error>{s.owner_before_owned(size_of::<Vec<U>>()+values.len().checked_mul(size_of::<U>()).expect("substitution vector layout"))?;let mut out=Vec::with_capacity(values.len());assert_eq!(out.capacity(),values.len(),"substitution vector exact capacity");for value in values{s.owner_work(1,0)?;out.push(copy(value)?)}Ok(out)}
pub(super) fn strings<S:IndustrialOwnerReadonlyFactsV1>(s:&S,values:&[String])->Result<Vec<String>,S::Error>{vector(s,values,|v|data::text(s,v))}
pub(super) fn impact<S:IndustrialOwnerReadonlyFactsV1>(s:&S,v:&SubstitutionImpactV1)->Result<SubstitutionImpactV1,S::Error>{s.owner_before_owned(size_of::<SubstitutionImpactV1>())?;Ok(SubstitutionImpactV1{outputs:data::profile(s,&v.outputs)?,quality:data::profile(s,&v.quality)?,power:data::profile(s,&v.power)?,time:data::profile(s,&v.time)?,byproducts:data::profile(s,&v.byproducts)?,terminal:data::profile(s,&v.terminal)?,value_class:data::profile(s,&v.value_class)?,logistics:data::profile(s,&v.logistics)?,buffer:data::profile(s,&v.buffer)?})}
pub(super) fn costs<S:IndustrialOwnerReadonlyFactsV1>(s:&S,v:&BTreeMap<String,u64>)->Result<BTreeMap<String,u64>,S::Error>{s.owner_before_owned(size_of::<BTreeMap<String,u64>>())?;let mut out=BTreeMap::new();for(key,value)in v{s.owner_work(1,0)?;data::tree_slot::<_,u64>(s,key,out.len())?;out.insert(data::text(s,key)?,*value);}Ok(out)}
pub(super) fn authority<S:IndustrialOwnerReadonlyFactsV1>(s:&S,v:&SubstitutionExecutionAuthorityV1)->Result<SubstitutionExecutionAuthorityV1,S::Error>{s.owner_before_owned(size_of::<SubstitutionExecutionAuthorityV1>())?;let selection=match &v.selection{SubstitutionSelectionV1::SameMaterialSource{source_lot,source_material}=>SubstitutionSelectionV1::SameMaterialSource{source_lot:data::reference(s,source_lot)?,source_material:data::profile(s,source_material)?},SubstitutionSelectionV1::ProfileRule{rule,source_lot,source_material}=>SubstitutionSelectionV1::ProfileRule{rule:data::profile(s,rule)?,source_lot:data::reference(s,source_lot)?,source_material:data::profile(s,source_material)?},SubstitutionSelectionV1::NewRecipe{candidate_root}=>SubstitutionSelectionV1::NewRecipe{candidate_root:data::reference(s,candidate_root)?}};
 Ok(SubstitutionExecutionAuthorityV1{authority_ref:data::reference(s,&v.authority_ref)?,owner_id:data::text(s,&v.owner_id)?,owner_binding_digest:data::text(s,&v.owner_binding_digest)?,factory_digest:data::text(s,&v.factory_digest)?,root_ref:data::reference(s,&v.root_ref)?,slot_id:data::text(s,&v.slot_id)?,expected_binding_revision:v.expected_binding_revision,profile_digest:data::text(s,&v.profile_digest)?,selection,target_recipe:data::text(s,&v.target_recipe)?,baseline_impacts:impact(s,&v.baseline_impacts)?,candidate_impacts:impact(s,&v.candidate_impacts)?,output_material:data::text(s,&v.output_material)?,output_unit:data::text(s,&v.output_unit)?,output_spec:data::text(s,&v.output_spec)?,output_quality:data::text(s,&v.output_quality)?,output_custody:data::text(s,&v.output_custody)?,owner_ledger_path_policy:data::profile(s,&v.owner_ledger_path_policy)?,input_state:data::text(s,&v.input_state)?,costs:costs(s,&v.costs)?,power_cost:v.power_cost,duration_ticks:v.duration_ticks,terminal_capacity:v.terminal_capacity,valid_until:v.valid_until,valuation:SubstitutionValuationV1{unit:data::text(s,&v.valuation.unit)?,held:v.valuation.held,consumed:v.valuation.consumed,expected_output:v.valuation.expected_output},risks:strings(s,&v.risks)?,next_recheck:v.next_recheck})
}
pub(super) fn rule<S:IndustrialOwnerReadonlyFactsV1>(s:&S,v:&SubstitutionRuleV1)->Result<SubstitutionRuleV1,S::Error>{s.owner_before_owned(size_of::<SubstitutionRuleV1>())?;let conversion=match &v.conversion{SubstitutionConversionV1::None=>SubstitutionConversionV1::None,SubstitutionConversionV1::Required{converter}=>SubstitutionConversionV1::Required{converter:data::profile(s,converter)?}};Ok(SubstitutionRuleV1{rule:data::profile(s,&v.rule)?,recipe:data::profile(s,&v.recipe)?,input_edge:data::text(s,&v.input_edge)?,required_material:data::profile(s,&v.required_material)?,allowed_materials:vector(s,&v.allowed_materials,|v|data::profile(s,v))?,accepted_specs:strings(s,&v.accepted_specs)?,accepted_quality:strings(s,&v.accepted_quality)?,accepted_custody:strings(s,&v.accepted_custody)?,owner_ledger_path_policy:data::profile(s,&v.owner_ledger_path_policy)?,source_unit:data::text(s,&v.source_unit)?,target_unit:data::text(s,&v.target_unit)?,ratio_numerator:v.ratio_numerator,ratio_denominator:v.ratio_denominator,executable_target_quantum:v.executable_target_quantum,rounding:v.rounding,residual:v.residual,aggregation_domain:data::profile(s,&v.aggregation_domain)?,source_loss_numerator:v.source_loss_numerator,source_loss_denominator:v.source_loss_denominator,impacts:impact(s,&v.impacts)?,conversion,applicable_input_states:strings(s,&v.applicable_input_states)?,disposition_policy:data::profile(s,&v.disposition_policy)?,recheck_policy:data::profile(s,&v.recheck_policy)?})}
pub(super) fn request<S:IndustrialOwnerReadonlyFactsV1>(s:&S,v:&SubstitutionPreviewRequestV1)->Result<SubstitutionPreviewRequestV1,S::Error>{s.owner_before_owned(size_of::<SubstitutionPreviewRequestV1>())?;Ok(SubstitutionPreviewRequestV1{root_ref:data::reference(s,&v.root_ref)?,slot_id:data::text(s,&v.slot_id)?,authority_refs:vector(s,&v.authority_refs,|v|data::reference(s,v))?})}
